  this.el('wave').innerHTML=title(trendLabels[v.trendKey]+(v.trendKey==='temperature'?' · '+tu:''),'02')+`<div class="ins-wave-head">${n(displayedTrend[0],v.trendKey==='temperature'?1:0)}<span>→ ${n(displayedTrend.at(-1),v.trendKey==='temperature'?1:0)}</span></div>`+insWave(displayedTrend,'main')+`<small>${v.interval} · ${c('示意','ILLUSTRATIVE')}</small>`;
  const barLabel=v.barKey==='low'?c('低云','LOW CLOUD'):v.barKey==='high'?c('高云','HIGH CLOUD'):v.barKey==='humidity'?c('相对湿度','RELATIVE HUMIDITY'):c('降水概率','PRECIP CHANCE');
